function note(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),1800)}
function drawCats(){const rank=categories.slice(0,4).map(c=>`<div><i style="background:${colors[c[0]]}"></i><b>${c[0]}<span>${mode==='share'?c[3]+'% of spending':(c[6]>0?'+':'')+c[6]+'% vs June'}</span></b><b>${money(c[2])}</b></div>`).join('');$('rank').innerHTML=rank;$('cats').innerHTML=categories.map((c,i)=>`<button class="cat ${i===selected?'sel':''}" data-cat="${i}"><span class="catIcon" style="background:${colors[c[0]]}18;color:${colors[c[0]]}">${c[1]}</span><span><span class="catLine"><b>${c[0]}</b><small>${c[4]} transactions</small></span><span class="sub">${c[5]}</span><span class="bar"><i style="width:${c[3]/32*100}%;background:${colors[c[0]]}"></i></span></span><span class="value"><b>${money(c[2])}</b><small>${mode==='share'?c[3]+'%':(c[6]>0?'+':'')+c[6]+'%'}</small></span></button>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{selected=+b.dataset.cat;drawCats()});const c=categories[selected];$('donutValue').textContent=mode==='share'?c[3]+'%':(c[6]>0?'+':'')+c[6]+'%';$('donutLabel').textContent=c[0];$('spotIcon').textContent=c[1];$('spotName').textContent=c[0];$('spotAmt').textContent=money(c[2]);$('merchant').textContent=c[5].split(' · ')[0];$('spotCount').textContent=c[4]+' transactions'}
function drawTx(){let list=tx.filter(t=>(filter==='all'||t[6]===filter||(filter==='review'&&t[7]==='review'))&&(`${t[1]} ${t[3]} ${t[4]}`.toLowerCase().includes(query.toLowerCase())));if(!newest)list=[...list].reverse();const groups={};list.forEach(t=>(groups[t[0]]??=[]).push(t));$('transactions').innerHTML=Object.entries(groups).map(([d,a])=>`<section class="dateCard card"><div class="dateHead"><b>${d}</b><span>${a.length} items</span></div>${a.map(t=>`<button class="txn" data-tx="${tx.indexOf(t)}"><span class="merchant" style="background:${colors[t[3]]}18;color:${colors[t[3]]}">${t[2]}</span><span class="txnCopy"><b>${t[1]}</b><span>${t[3]} · ${t[4]}</span>${t[7]==='review'?'<span class="tag">Needs review</span>':''}</span><span class="amount ${t[5]>0?'credit':''}"><b>${t[5]>0?'+':''}${money(t[5])}</b><span>${t[6]==='transfer'?'Not spending':t[5]>0?'Money in':'Spending'}</span></span></button>`).join('')}</section>`).join('')||'<section class="card" style="padding:28px;text-align:center;color:#6d7e85">No matching transactions.</section>';document.querySelectorAll('[data-tx]').forEach(b=>b.onclick=()=>openTx(+b.dataset.tx))}
function openTx(i){const t=tx[i];$('sheetBody').innerHTML=`<div class="sheetTop"><span class="merchant" style="background:${colors[t[3]]}18;color:${colors[t[3]]}">${t[2]}</span><div><h2>${t[1]}</h2><p>${t[3]} · ${t[4]}</p></div><div class="big">${t[5]>0?'+':''}${money(t[5])}</div></div><div class="details"><div class="detail"><small>Spending effect</small><b>${t[6]==='transfer'?'None':t[5]>0?'Reduces / money in':'Increases spending'}</b></div><div class="detail"><small>Review state</small><b>${t[7]==='review'?'Needs review':'Confirmed'}</b></div><div class="detail"><small>When</small><b>${t[0]}, ${t[8]}</b></div><div class="detail"><small>Account</small><b>${t[4]}</b></div></div><div class="source">Source SMS and parser details remain collapsed in the intended final product.</div>`;openSheet()}
function openSheet(){ $('shade').classList.add('on');$('sheet').classList.add('on') }function close(){ $('shade').classList.remove('on');$('sheet').classList.remove('on') }
function nextUnresolved(start=0){for(let n=0;n<reviewItems.length;n++){const i=(start+n)%reviewItems.length;if(!resolved.has(reviewItems[i].id))return i}return-1}
function updateReviewSummary(){const done=resolved.size,remaining=reviewItems.length-done,pct=Math.round(done/reviewItems.length*100);$('remainingBig').textContent=remaining;$('reviewBadge').textContent=remaining;$('reviewBadge').style.display=remaining?'grid':'none';document.querySelectorAll('.reviewRemainingText').forEach(x=>x.textContent=remaining);$('reviewProgress').style.width=pct+'%';$('reviewProgressLabel').textContent=`${done} of ${reviewItems.length} resolved`;const active=reviewItems.filter(x=>!resolved.has(x.id));$('merchantReasonCount').textContent=active.filter(x=>x.type==='merchant').length;$('categoryReasonCount').textContent=active.filter(x=>x.type==='category').length;$('sourceReasonCount').textContent=active.filter(x=>x.type==='source').length}
function drawReview(){updateReviewSummary();const remaining=reviewItems.length-resolved.size;if(!remaining){$('reviewWorkspace').innerHTML=`<section class="card" style="padding:28px 18px;text-align:center;margin-bottom:11px"><div style="width:58px;height:58px;margin:auto;border-radius:20px;background:#e8f6f2;color:#08766e;display:grid;place-items:center;font-size:27px">✓</div><h2 style="margin:14px 0 5px">Review complete</h2><p style="margin:0;color:var(--muted);font-size:11px;line-height:1.5">All uncertain items are resolved. Your category totals and activity are now up to date.</p><button class="primary" style="margin-top:16px" data-screen-jump="overview">Back to Overview</button></section>`;$('reviewQueue').innerHTML='';bindJumps();return}if(resolved.has(reviewItems[currentReview].id))currentReview=nextUnresolved(currentReview+1);const r=reviewItems[currentReview];$('reviewWorkspace').innerHTML=`<section class="reviewCard card"><div class="reviewCardHead"><div class="issueRow"><span class="issueBadge">● ${r.reason}</span><span class="queuePos">${resolved.size+1} of ${reviewItems.length}</span></div><div class="reviewMerchant"><span class="merchant">${r.initials}</span><div><h2>${r.merchant}</h2><p>${r.when} · ${r.account}</p></div><div class="reviewAmount"><b>${r.amount>0?'+':''}${money(r.amount)}</b><small>${r.amount>0?'Credit':'Transaction'}</small></div></div></div><div class="reviewBody"><div class="question">${r.question}</div><div class="hint">${r.hint}</div><div class="choiceGrid">${r.choices.map(c=>`<button class="choice ${r.selected===c[0]?'on':''}" data-choice="${c[0]}"><span class="choiceIcon" style="background:${colors[c[0]]||'#e8f1ee'}22;color:${colors[c[0]]||'var(--teal)'}">${c[1]}</span><span><b>${c[0]}</b><small>${c[2]}</small></span></button>`).join('')}</div>${r.remember?`<label class="remember"><input id="rememberRule" type="checkbox" checked><span><b>Make this the default</b><span>${r.remember}</span></span></label>`:''}<div class="evidence" id="evidence"><button id="evidenceBtn">Why this needs review <span>⌄</span></button><div class="evidenceText">${r.evidence}<br><br>Only the minimum source context needed to explain the suggestion is shown.</div></div><div class="reviewActions"><button class="quiet" id="skipReview">Skip</button><button class="secondary" id="excludeReview">Exclude</button><button class="primary" id="confirmReview">Confirm & next</button></div></div></section>`;
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{r.selected=b.dataset.choice;drawReview()});$('evidenceBtn').onclick=()=>$('evidence').classList.toggle('open');$('skipReview').onclick=()=>{currentReview=nextUnresolved(currentReview+1);note('Skipped for now');drawReview()};$('excludeReview').onclick=()=>{resolved.add(r.id);note('Excluded from spending');currentReview=nextUnresolved(currentReview+1);drawReview();drawTx()};$('confirmReview').onclick=()=>{resolved.add(r.id);note(`Confirmed: ${r.selected}`);currentReview=nextUnresolved(currentReview+1);drawReview();drawTx()};
 $('reviewQueue').innerHTML=reviewItems.map((item,i)=>`<button class="queueItem ${resolved.has(item.id)?'done':''}" data-review-index="${i}"><span class="merchant" style="background:${resolved.has(item.id)?'#edf2ef':reviewColor(item.type)+'18'};color:${reviewColor(item.type)}">${resolved.has(item.id)?'✓':item.initials}</span><span><b>${item.merchant}</b><span>${item.reason}</span></span><span class="queueState">${resolved.has(item.id)?'Done':i===currentReview?'Now':'Open'}</span></button>`).join('');document.querySelectorAll('[data-review-index]').forEach(b=>b.onclick=()=>{const i=+b.dataset.reviewIndex;if(!resolved.has(reviewItems[i].id)){currentReview=i;drawReview();scrollTo(0,0)}})}
